source_context:
 1: ---
 2: - name: "WordPress Server: Install LEMP Stack with PHP and MariaDB MySQL"
 3:   hosts: web:&development
 4:   become: yes
 5: 
 6:   roles:
 7:     - { role: common, tags: [common] }
 8:     - { role: fail2ban, tags: [fail2ban] }
 9:     - { role: ferm, tags: [ferm] }
10:     - { role: hosts, tags: [hosts] }
11:     - { role: ntp, tags: [ntp] }
12:     - { role: sshd, tags: [sshd] }
13:     - { role: mariadb, tags: [mariadb] }
14:     - { role: mailpit, tags: [mailpit, mailhog, mail] }
15:     - { role: php, tags: [php] }
16:     - { role: xdebug, tags: [php, xdebug] }
17:     - { role: memcached, tags: [memcached], when: sites_using_memcached | count > 0 }
18:     - { role: redis, tags: [redis], when: sites_using_redis | count > 0 }
19:     - { role: nginx, tags: [nginx] }
20:     - { role: logrotate, tags: [logrotate] }
21:     - { role: composer, tags: [composer] }
22:     - { role: wp-cli, tags: [wp-cli] }
23:     - { role: wordpress-setup, tags: [wordpress, wordpress-setup] }
24:     - { role: wordpress-install, tags: [wordpress, wordpress-install] }

 1: - name: Cluster {{ cluster_id }} - Create directories
 2:   file:
 3:     path: "{{ item }}"
 4:     state: directory
 5:     mode: 0755 # For some reason, item.mode converts 0755 into 493 ... weird
 6:   loop:
 7:     - clusters/{{ cluster_id }}
 8: 
 9: - name: Cluster {{ cluster_id }} - Create openshift-install configuration
10:   template:
11:     src: "{{ item.src }}"
12:     dest: "{{ item.dest }}"
13:   vars:
14:     ssh_pub_key: "{{ ssh_pub_key_task.stdout }}"
15:     pull_secret: "{{ lookup('file', './files/pull_secret.txt', errors='ignore') }}"
16:   with_items:
17:     - {
18:         src: templates/install-config.yaml.j2,
19:         dest: "clusters/{{ cluster_id }}/install-config.yaml",
20:       }
21:     - {
22:         src: templates/agent-config.yaml.j2,
23:         dest: "clusters/{{ cluster_id }}/agent-config.yaml",
24:       }
25:   register: okd_installer_config_files
26: 
27: # Let's create the proper OKD installation files (ignition, manifests, ...)
28: - name: Cluster {{ cluster_id }} - Run openshift-installer
29:   when: okd_installer_config_files.changed
30:   shell: |
31:     cd clusters/{{ cluster_id }}
32:     rm -rf install-dir
33:     mkdir install-dir
34:     cp install-config.yaml agent-config.yaml install-dir/
35:     {% if ipxe.enabled %}
36:       {% set cmd = "pxe-files" %}
37:     {% else %}
38:       {% set cmd = "image" %}
39:     {% endif %}
40:     openshift-install agent create {{ cmd }} --dir=install-dir
41:   environment:
42:     PATH: "/usr/local/bin:/usr/bin:/bin"
43:   register: installer_task
44: 
45: # Make these files available on the Web server
46: - name: Cluster {{ cluster_id }} - Copy boot-artifacts to www directory
47:   when: installer_task.changed
48:   become: true
49:   shell: |
50:     rm -rf /var/www/html/{{ cluster_id }}
51:     mkdir /var/www/html/{{ cluster_id }}
52:     {% if ipxe.enabled %}
53:     cp -R clusters/{{ cluster_id }}/install-dir/boot-artifacts/* /var/www/html/{{ cluster_id }}
54:     {% else %}
55:     cp clusters/{{ cluster_id }}/install-dir/agent.x86_64.iso /var/www/html/{{ cluster_id }}/
56:     {% endif %}
57:     chmod -R 755 /var/www/html/{{ cluster_id }}
